from scripts.porota_actions_host import connection, ssh_run

CONTROL = Path(sys.argv[1])
EXPECTED_PRODUCT = "a7b1bb9f4c508b301fe44252972fdcac70904226"
EXPECTED_TREE = "b0d18a34750e94a973e5dd5a27916fa7ff881786"

CONTAINER_EXTRA = "\"\"\"Additional bounded, sanitized reads for the incident RCA.\"\"\"\nfrom itertools import islice\nfrom shutil import disk_usage\nfrom cg_paper_workspace import artifact_root\nfrom rc6_backup_policy import backups_suspended\n\n\ndef small_json(path, limit=131072):\n    with path.open(\"rb\") as source:\n        raw = source.read(limit + 1)\n    if len(raw) > limit:\n        raise ValueError(\"ARTIFACT_OVERSIZE\")\n    data = json.loads(raw)\n    if not isinstance(data, dict):\n        raise ValueError(\"ARTIFACT_INVALID\")\n    return data\n\n\ndef sanitized_code(value):\n    if isinstance(value, str) and re.fullmatch(r\"[A-Z][A-Z0-9_]{0,95}\", value):\n        return value\n    return None\n\n\ndef worker_health(root):\n    data = small_json(root / \"runtime-health.json\")\n    roles = (\"ppi_gateway\", \"scanner\", \"dynamic_shadow\", \"exit_reader\", \"notifications\",\n             \"candles\", \"intraday_scalping\", \"caucion_cash_sweep\")\n    workers = {}\n    for role in roles:\n        row = data.get(\"children\", {}).get(role)\n        if not isinstance(row, dict):\n            workers[role] = {\"state\": \"MISSING\"}\n            continue\n        pid = row.get(\"pid\")\n        alive = None\n        if type(pid) is int and pid > 0:\n            try:\n                with Path(f\"/proc/{pid}/stat\").open(\"r\", encoding=\"ascii\") as handle:\n                    alive = handle.read(4096).rsplit(\") \", 1)[1].split()[0] in {\"R\", \"S\", \"D\", \"I\"}\n            except (OSError, IndexError, UnicodeError):\n                alive = False\n        workers[role] = {\"state\": sanitized_code(row.get(\"state\")), \"alive\": alive,\n                         \"started_at\": timestamp(row.get(\"started_at\")),\n                         \"last_exit_at\": timestamp(row.get(\"last_exit_at\")),\n                         \"last_error\": sanitized_code(row.get(\"last_error\"))}\n    budget = data.get(\"ppi_budget\") or {}\n    exit_service = budget.get(\"exit_service\") or {}\n    round_state = exit_service.get(\"round\") or {}\n    sale = data.get(\"fixed_income_sale\") or {}\n    raise_if = data.get(\"mode\") != \"PRODUCTION_PAPER\" or type(data.get(\"real_orders_sent\")) is not int or data[\"real_orders_sent\"] != 0\n    if raise_if:\n        raise ValueError(\"CHILD_HEALTH_PAPER_REQUIRED\")\n    return {\"recorded_at\": timestamp(data.get(\"recorded_at\")),\n            \"source_binding\": data.get(\"source_sha\") == \"98efb2a1bc1d4e1ea74dd6d166da646245b058f9\",\n            \"workers\": workers, \"budget_status\": sanitized_code(budget.get(\"status\")),\n            \"budget_round_status\": sanitized_code(round_state.get(\"status\")),\n            \"budget_round_reason\": sanitized_code(round_state.get(\"reason\")),\n            \"fixed_income_sale_state\": sanitized_code(sale.get(\"state\")),\n            \"fixed_income_sale_variants\": count(sale.get(\"variants\"))}\n\n\ndef backup_capacity(source, directory):\n    if not source.is_file():\n        return {\"status\": \"SOURCE_NOT_AVAILABLE\"}\n    destination = directory if directory.is_dir() else next(\n        (parent for parent in directory.parents if parent.is_dir()), None)\n    if destination is None:\n        return {\"status\": \"DESTINATION_UNAVAILABLE\"}\n    source_bytes = source.stat().st_size\n    usage = disk_usage(destination)\n    reserve = 2 * source_bytes + 2 * 1024 ** 3\n    return {\"status\": \"OBSERVED\", \"destination_exists\": directory.is_dir(),\n            \"source_bytes\": source_bytes, \"available_bytes\": usage.free,\n            \"filesystem_total_bytes\": usage.total, \"required_bytes\": reserve,\n            \"admitted_by_capacity_now\": usage.free >= reserve}\n\n\ndef backup_job(row):\n    key, ran, success, state, detail = row\n    reserve = re.search(r\"DISK_RESERVE_BLOCKED\\|available=(\\d{1,18})\\|required=(\\d{1,18})\", detail or \"\")\n    return {\"job\": key, \"last_run_at\": timestamp(ran), \"last_success_at\": timestamp(success),\n            \"state\": sanitized_code(state), \"stored_available_bytes\": int(reserve[1]) if reserve else None,\n            \"stored_required_bytes\": int(reserve[2]) if reserve else None}\n\n\ndef db_receipt(database):\n    result = {}\n    with closing(sqlite3.connect(database.as_uri() + \"?mode=ro\", uri=True, timeout=.25)) as c:\n        c.execute(\"PRAGMA query_only=ON\")\n        c.execute(\"BEGIN\")\n        deadline = time.monotonic() + 2.0\n        c.set_progress_handler(lambda: int(time.monotonic() > deadline), 1000)\n        identity_from_connection(c)\n        checked_mode, checked_real = c.execute(\"SELECT mode,real_orders_sent FROM observer_state WHERE id=1\").fetchone()\n        if checked_mode != \"PRODUCTION_PAPER\" or type(checked_real) is not int or checked_real:\n            raise ValueError(\"PAPER_ZERO_REQUIRED\")\n        heartbeat, state, detail = c.execute(\n            \"SELECT heartbeat_at,state,detail FROM paper_exit_reader_state WHERE id=1\").fetchone()\n        match = re.fullmatch(r\"(\\d+) errores de lectura de abiertas; round_seconds=([0-9.]+); \"\n                             r\"(?:baseline_cadence=NO_VERIFICADO|critical_cadence_seconds=([0-9.]+); \"\n                             r\"deadline_missed=(True|False)); budget_round=([A-Z_]+)\", detail or \"\")\n        result[\"exit_reader\"] = {\"heartbeat\": timestamp(heartbeat), \"state\": sanitized_code(state),\n                                 \"round_kind\": match[5] if match else \"UNCLASSIFIED\",\n                                 \"round_failures\": int(match[1]) if match else None,\n                                 \"round_elapsed_seconds\": float(match[2]) if match else None,\n                                 \"approved_cadence_seconds\": float(match[3]) if match and match[3] else None,\n                                 \"deadline_missed\": match[4] == \"True\" if match and match[4] else None,\n                                 \"sqlite_contention\": \"SQLite contention\" in (detail or \"\")}\n        result[\"backup_jobs\"] = [backup_job(row) for row in c.execute(\n            \"SELECT job_key,last_run_at,last_success_at,state,detail FROM operational_jobs \"\n            \"WHERE job_key IN ('DAILY_BACKUP','HISTORY_BACKUP','SRE_SNAPSHOT')\")]\n        result[\"backup_receipts\"] = [\n            {\"kind\": sanitized_code(kind), \"created_at\": timestamp(stamp), \"size_bytes\": size,\n             \"restore_result\": sanitized_code(restore), \"state\": sanitized_code(state),\n             \"file_present\": Path(saved).is_file() if isinstance(saved, str) else None}\n            for kind, stamp, size, restore, state, saved in c.execute(\n                \"SELECT kind,created_at,size_bytes,restore_test,state,path FROM backup_runs ORDER BY id DESC LIMIT 6\")]\n        result[\"scanner_cycles\"] = [\n            {\"finished_at\": timestamp(at), \"eligible\": count(eligible), \"selected\": count(selected),\n             \"successful\": count(success), \"failed\": count(failed),\n             \"cursor_delta\": after - before if type(before) is int and type(after) is int else None}\n            for at, eligible, selected, success, failed, before, after in c.execute(\n                \"SELECT finished_at,eligible_total,selected_count,successful_count,failed_count,cursor_before,cursor_after \"\n                \"FROM universe_cycle_metrics ORDER BY id DESC LIMIT 16\")]\n        result[\"iol\"] = [\n            {\"component\": sanitized_code(name), \"state\": sanitized_code(state),\n             \"checked_at\": timestamp(checked), \"last_success_at\": timestamp(success)}\n            for name, state, checked, success in c.execute(\n                \"SELECT component,state,checked_at,last_success_at FROM api_health \"\n                \"WHERE component LIKE 'IOL%' ORDER BY component LIMIT 16\")]\n        since = (datetime.now(timezone.utc) - timedelta(hours=1)).isoformat()\n        result[\"decisions_last_hour\"] = c.execute(\n            \"SELECT COUNT(*) FROM (SELECT decided_at FROM paper_decisions ORDER BY id DESC LIMIT 2000) \"\n            \"WHERE julianday(decided_at) >= julianday(?)\", (since,)).fetchone()[0]\n        result[\"active_paper_positions\"] = {\n            \"spot\": c.execute(\"SELECT COUNT(*) FROM paper_positions WHERE status='OPEN'\").fetchone()[0],\n            \"futures\": c.execute(\"SELECT COUNT(*) FROM paper_future_positions WHERE status='ACTIVE'\").fetchone()[0]}\n        for table in (\"market_snapshots\", \"paper_decisions\", \"paper_events\", \"paper_fills\"):\n            result.setdefault(\"cursors\", {})[table] = c.execute(f\"SELECT MAX(id) FROM {table}\").fetchone()[0]\n    return result\n\n\nextra = {}\nroot = artifact_root(database)\nfor name, probe in (\n    (\"controller\", lambda: worker_health(root)),\n    (\"sqlite_detail\", lambda: db_receipt(database)),\n    (\"backup_policy\", lambda: {\n        \"suspended_by_policy\": backups_suspended(),\n        \"observer\": backup_capacity(database, root / \"backups\" / \"paper\"),\n        \"history\": backup_capacity(Path(os.getenv(\"HIST_DB_PATH\", \"data/market_history.db\")).resolve(),\n                                   root / \"backups\" / \"history\")}),\n):\n    try:\n        extra[name] = probe()\n    except (KeyError, TypeError, ValueError, OSError, sqlite3.Error) as exc:\n        extra[name] = {\"status\": \"NO_VERIFICADO\", \"error_class\": type(exc).__name__}\nextra[\"direct_rest_recovery_configured\"] = os.getenv(\"POROTA_PPI_DIRECT_REST_RECOVERY\") == \"1\"\noutput[\"rca\"] = extra\n\nimport json\nimport os\nfrom pathlib import Path\nimport re\n\nfrom cg_paper_workspace import database_path\nfrom rc6_scheduler_snapshot import systemd_clock\nfrom rc6_shadow_runtime.funnel import STAGES\nfrom rc6_trader_dashboard.datasets import artifact\nfrom rc6_trader_dashboard.projection import Projection, Store\n\n\ndef snapshot_time(value):\n    from datetime import datetime\n    if not isinstance(value, str) or len(value) > 40:\n        return None\n    try:\n        stamp = datetime.fromisoformat(value.replace(\"Z\", \"+00:00\"))\n        return stamp.isoformat() if stamp.tzinfo else None\n    except ValueError:\n        return None\n\n\ndef counts_by_stage(projection):\n    cut = projection.shadow\n    result = {\"state\": \"NO_VERIFICADO\", \"by_currency_channel\": [],\n              \"by_family_and_stage\": \"NOT_IN_COMPACT_CURRENT\"}\n    if not projection.shadow_fresh:\n        result[\"reason\"] = \"CURRENT_NOT_FRESH_OR_UNAVAILABLE\"\n        return result\n    report = cut[\"report\"]\n    funnel = report.get(\"operational_funnel\", {})\n    groups = funnel.get(\"by_currency_channel\", [])\n    if not isinstance(groups, list) or len(groups) > 64:\n        result[\"reason\"] = \"CURRENT_FUNNEL_GROUPS_UNAVAILABLE\"\n        return result\n    currencies = {\"ARS\", \"USD\", \"USD_CCL\", \"USD_MEP\", \"USD_EXT\", \"EXT\", \"MEP\", \"CCL\",\n                  \"EUR\", \"BRL\", \"CLP\", \"UYU\", \"JPY\", \"GBP\", \"CHF\", \"USDT\", \"USDC\"}\n    channels = {\"NATIVE_FACTUAL\", \"UNIVERSE_SHADOW\", \"FAMILY_OBSERVE_ONLY\",\n                \"SHADOW_ENTRY_EXPERIMENT\"}\n    for row in groups:\n        if not isinstance(row, dict) or row.get(\"currency\") not in currencies or row.get(\"channel\") not in channels:\n            result[\"reason\"] = \"CURRENT_FUNNEL_UNRECOGNIZED_COHORT\"\n            result[\"by_currency_channel\"] = []\n            return result\n        stages = row.get(\"stages\")\n        if not isinstance(stages, dict) or any(key not in STAGES or type(value) is not int or not 0 <= value <= 120000\n                                                for key, value in stages.items()):\n            result[\"reason\"] = \"CURRENT_FUNNEL_COUNTS_INVALID\"\n            result[\"by_currency_channel\"] = []\n            return result\n        result[\"by_currency_channel\"].append({\"currency\": row[\"currency\"], \"channel\": row[\"channel\"],\n                                               \"stages\": {stage: stages.get(stage, 0) for stage in STAGES}})\n    status = funnel.get(\"status\")\n    if status not in {\"START_AT_CURRENT_TAIL\", \"PROSPECTIVE_OPERATIONAL_FUNNEL_EVALUATED\"}:\n        result[\"reason\"] = \"CURRENT_FUNNEL_NOT_PUBLISHED\"\n        result[\"by_currency_channel\"] = []\n        return result\n    result.update(state=\"OBSERVED\", status=status, as_of=snapshot_time(funnel.get(\"as_of\")),\n                  current_as_of=snapshot_time(report.get(\"as_of\")),\n                  generation_id=cut[\"pointer\"][\"generation_id\"],\n                  real_orders_sent=report[\"real_orders_sent\"], real_routes=report[\"real_routes\"])\n    return result\n\n\ndef timers(projection):\n    path = Path(os.getenv(\"POROTA_SCHEDULER_STATE_PATH\", \"data/scheduler/systemd_timers.json\"))\n    payload, source = projection.bounded_file(path.name, root=path.parent)\n    result = {\"state\": \"NO_VERIFICADO\", \"freshness\": \"NO_VERIFICADO\", \"timers\": []}\n    raw_timers = payload.get(\"timers\")\n    if (source != \"AVAILABLE\" or payload.get(\"schema\") != \"porota-scheduler-systemd-v1\"\n            or not isinstance(raw_timers, list) or len(raw_timers) > 128):\n        result[\"reason\"] = \"SCHEDULER_SNAPSHOT_UNAVAILABLE_OR_UNBOUNDED\"\n        return result\n\n    # Use the deployed reader's own state/freshness logic on a single fixed sample.\n    projection.bounded_file = lambda *args, **kwargs: (payload, source)\n    result[\"as_of\"] = snapshot_time(payload.get(\"recorded_at\"))\n    result[\"total_exported\"] = len(raw_timers)\n    skipped = 0\n    for offset in range(0, max(1, len(raw_timers)), 10):\n        projection.offset = offset\n        page = artifact(projection, \"scheduler\")\n        result[\"freshness\"] = page.state if page.state in {\"FRESH\", \"STALE\"} else \"NO_VERIFICADO\"\n        for row in page.rows:\n            unit, service = row.get(\"unit\"), row.get(\"service\")\n            identifiers = [re.sub(r\"[^a-z]\", \"\", name.lower()) for name in (unit, service) if isinstance(name, str)]\n            if (not isinstance(unit, str) or not re.fullmatch(r\"porota-[A-Za-z0-9_.@-]{1,100}\\.timer\", unit)\n                    or any(alias in identifier for alias in (\"ppiwatch\", \"ppiapiwatch\") for identifier in identifiers)):\n                skipped += 1\n                continue\n            clean = {\"unit\": unit}\n            if isinstance(service, str) and re.fullmatch(r\"porota-[A-Za-z0-9_.@-]{1,100}\\.service\", service):\n                clean[\"service\"] = service\n            states = {\n                \"state\": {\"SERVICE_FAILED\", \"SUSPENDED\", \"Instantánea publicada\", \"En ejecución al capturar\",\n                          \"TIMER_ACTIVE\", \"NO_VERIFICADO\"},\n                \"active\": {\"active\", \"inactive\", \"activating\", \"deactivating\", \"failed\", \"maintenance\", \"unknown\"},\n                \"enabled\": {\"enabled\", \"enabled-runtime\", \"masked\", \"masked-runtime\", \"disabled\", \"static\",\n                            \"alias\", \"generated\", \"transient\", \"indirect\", \"linked\", \"linked-runtime\", \"unknown\"},\n                \"execution_state\": {\"RUNNING\", \"COMPLETED\", \"NO_EXECUTION_OBSERVED\", \"UNIT_UNAVAILABLE\", \"UNKNOWN\"},\n                \"last_result\": {\"success\", \"exit-code\", \"signal\", \"core-dump\", \"watchdog\", \"timeout\", \"resources\",\n                                \"start-limit-hit\", \"oom-kill\", \"protocol\", \"unknown\"},\n            }\n            for key, allowed in states.items():\n                value = row.get(key)\n                clean[key] = value if isinstance(value, str) and value in allowed else \"NO_VERIFICADO\"\n            for key in (\"last_run\", \"next_run\"):\n                clean[key] = snapshot_time(row.get(key))\n            for key in (\"service_started_at\", \"service_finished_at\"):\n                value = systemd_clock(row.get(key))\n                clean[key] = value.isoformat() if value else None\n            for key in (\"exec_main_code\", \"exec_main_status\"):\n                value = row.get(key)\n                clean[key] = int(value) if type(value) is int and 0 <= value <= 255 else (\n                    int(value) if isinstance(value, str) and re.fullmatch(r\"\\d{1,3}\", value) and int(value) <= 255 else None)\n            result[\"timers\"].append(clean)\n    result[\"excluded_rows\"] = skipped\n    if result[\"freshness\"] == \"FRESH\" and len(result[\"timers\"]) + skipped == len(raw_timers):\n        result[\"state\"] = \"OBSERVED\" if not skipped else \"PARTIAL\"\n    return result\n\n\nprojection = Projection(Store(database_path()))\nresult = {}\nfor name, probe in ((\"funnel\", counts_by_stage), (\"scheduler\", timers)):\n    try:\n        result[name] = probe(projection)\n    except (AttributeError, KeyError, OSError, RuntimeError, TypeError, ValueError):\n        result[name] = {\"state\": \"NO_VERIFICADO\", \"reason\": \"READ_CONTRACT_REJECTED\"}\noutput[\"funnel_and_timers\"] = result"
HOST_LOCK = "\"\"\"Project the kernel's current lock owners without taking the deploy lock.\"\"\"\nimport os\nfrom pathlib import Path\nimport re\nimport stat\n\n\ndef bounded_text(path, limit):\n    with path.open(\"r\", encoding=\"ascii\", errors=\"replace\") as src:\n        value = src.read(limit + 1)\n    if len(value) > limit:\n        raise ValueError(\"READ_LIMIT\")\n    return value\n\n\ndef lock_evidence(context):\n    path = context.host.identity.state / \"deploy.lock\"\n    info = path.lstat()\n    if not stat.S_ISREG(info.st_mode) or info.st_uid != context.host.identity.uid or info.st_nlink != 1:\n        raise ValueError(\"UNSAFE_LOCK_IDENTITY\")\n    target = (os.major(info.st_dev), os.minor(info.st_dev), info.st_ino)\n    holders = []\n    for line in bounded_text(Path(\"/proc/locks\"), 262144).splitlines():\n        columns = line.split()\n        if len(columns) < 8 or columns[1] != \"FLOCK\":\n            continue\n        match = re.fullmatch(r\"([0-9a-fA-F]+):([0-9a-fA-F]+):(\\d+)\", columns[5])\n        if not match or (int(match[1], 16), int(match[2], 16), int(match[3])) != target:\n            continue\n        process = Path(\"/proc\") / str(int(columns[4]))\n        unit = \"NOT_IDENTIFIED\"\n        try:\n            cgroup = bounded_text(process / \"cgroup\", 8192)\n            candidate = re.search(r\"(?<![A-Za-z0-9_-])(porota-[a-zA-Z0-9_@.-]{1,88}\\.service)(?=/|[\\n ]|$)\", cgroup)\n            if candidate and not any(w in candidate[1].lower().replace(\"-\", \"\") for w in (\"ppiwatch\", \"ppiapiwatch\")):\n                unit = candidate[1]\n        except (ValueError, OSError):\n            pass\n        holders.append({\"mode\": {\"READ\": \"SHARED\", \"WRITE\": \"EXCLUSIVE\"}.get(columns[3], \"UNKNOWN\"),\n                        \"unit\": unit, \"sampled_at\": datetime.now(timezone.utc).isoformat()})\n        if len(holders) == 12:\n            break\n    return {\"status\": \"OBSERVED\", \"kernel_flock_holders\": holders, \"count\": len(holders)}\n\n\ntry:\n    lock_receipt = lock_evidence(context)\nexcept (OSError, TypeError, ValueError):\n    lock_receipt = {\"status\": \"NO_VERIFICADO\", \"reason\": \"LOCK_EVIDENCE_UNAVAILABLE\"}"

def main():
    monitor = (CONTROL / "scripts/rc6_market_watch_readonly.py").read_text(encoding="utf-8")
    probe = Path(__file__).with_name("observer_probe.py").read_text(encoding="utf-8")
    marker = 'print(json.dumps(output, separators=(",", ":"), sort_keys=True))'
    if probe.count(marker) != 1:
        raise ValueError("PROBE_SOURCE_CHANGED")
    probe = probe.replace(marker, CONTAINER_EXTRA + "\n" + marker)
    remote = f"""
from datetime import datetime, timezone
import json
import sys
import types

receipt = {{"status": "NO_VERIFICADO", "read_only": True, "observed_at": datetime.now(timezone.utc).isoformat()}}
try:
    monitor = types.ModuleType("_rc6_market_watch")
    monitor.__file__ = "rc6_market_watch_readonly.py"
    sys.modules[monitor.__name__] = monitor
    exec(compile({monitor!r}, monitor.__file__, "exec"), monitor.__dict__)
    context = monitor._rootless_context()
    if (context.current.get("source_tree") != {EXPECTED_TREE!r}
            or context.current.get("deployment_sha") != {EXPECTED_PRODUCT!r}
            or context.items["observer"]["State"].get("Running") is not True):
        raise ValueError("PRODUCT_BINDING_UNVERIFIED")
    result = context.host.docker.command_result(
        "container", "exec", "-w", "/app", context.roles["observer"], "python", "-B", "-c",
        {probe!r}, timeout=23)
    if result.returncode or len(result.stdout) > 80000:
        raise ValueError("CONTAINER_RECEIPT_UNAVAILABLE")
    data = json.loads(result.stdout)
    identity = context.host.identity
    if (data.get("real_orders_sent") != 0 or
            monitor._read_private_current(identity.state / "current.json", identity.uid) != context.current):
        raise ValueError("PRODUCT_BINDING_UNVERIFIED")
    lock_scope = {{"context": context, "datetime": datetime, "timezone": timezone}}
    exec(compile({HOST_LOCK!r}, "<deploy-lock-read>", "exec"), lock_scope)
    receipt.update(data=data, status="OBSERVED", source_sha=context.current["source_sha"],
                   deploy_lock=lock_scope["lock_receipt"],
                   source_tree=context.current["source_tree"], provider_requests_by_probe=0,
                   telegram_sends_by_probe=0, sqlite_writes_by_probe=0)
except (AttributeError, KeyError, OSError, RuntimeError, TypeError, ValueError) as error:
    allowed = ("PRODUCT_BINDING_UNVERIFIED", "CONTAINER_RECEIPT_UNAVAILABLE")
    receipt["reason"] = str(error) if type(error) is ValueError and str(error) in allowed else "HOST_PROBE_UNAVAILABLE"
print(json.dumps(receipt, separators=(",", ":")))
"""
    try:
        with connection(os.environ) as (ssh, _, _):
            result = ssh_run(ssh, ["timeout", "36", "/usr/bin/python3", "-B", "-"],
                             data=remote.encode(), timeout=47)
        if result.returncode or len(result.stdout) > 84000:
            raise ValueError("SSH_READ_RECEIPT_UNAVAILABLE")
        receipt = json.loads(result.stdout)
        if not isinstance(receipt, dict) or receipt.get("read_only") is not True:
            raise ValueError("SSH_READ_RECEIPT_INVALID")
    except (OSError, RuntimeError, ValueError):
        receipt = {"status": "NO_VERIFICADO", "reason": "SSH_READ_PROBE_UNAVAILABLE"}
    print(json.dumps(receipt, separators=(",", ":")))
    return 0 if receipt.get("status") == "OBSERVED" else 2

if __name__ == "__main__":
    raise SystemExit(main())
